-- Baseline schema for the forum modular monolith.
-- Target: MariaDB 10.6.8, InnoDB, utf8mb4 / utf8mb4_unicode_ci.
-- Rules: BIGINT primary keys generated by the application (snowflake ids),
-- every table carries create_time, mutable tables carry update_time, soft
-- deletes use is_deleted, booleans are TINYINT and counters default to 0.

-- ---------------------------------------------------------------------------
-- RBAC: roles, permissions and their mapping tables
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS sys_role (
    id          BIGINT       NOT NULL,
    code        VARCHAR(64)  NOT NULL,
    name        VARCHAR(64)  NOT NULL,
    description VARCHAR(255) DEFAULT NULL,
    create_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_role_code (code)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sys_permission (
    id          BIGINT       NOT NULL,
    code        VARCHAR(96)  NOT NULL,
    name        VARCHAR(96)  NOT NULL,
    module      VARCHAR(64)  NOT NULL,
    description VARCHAR(255) DEFAULT NULL,
    create_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_permission_code (code),
    KEY idx_permission_module (module)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sys_role_permission (
    id            BIGINT   NOT NULL,
    role_id       BIGINT   NOT NULL,
    permission_id BIGINT   NOT NULL,
    create_time   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_role_permission (role_id, permission_id),
    KEY idx_role_permission_role (role_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sys_user_role (
    id          BIGINT   NOT NULL,
    user_id     BIGINT   NOT NULL,
    role_id     BIGINT   NOT NULL,
    create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_user_role (user_id, role_id),
    KEY idx_user_role_role (role_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Users and authentication
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS sys_user (
    id            BIGINT       NOT NULL,
    username      VARCHAR(64)  NOT NULL,
    email         VARCHAR(128) DEFAULT NULL,
    password_hash VARCHAR(100) NOT NULL,
    nickname      VARCHAR(64)  NOT NULL,
    avatar_url    VARCHAR(255) DEFAULT NULL,
    bio           VARCHAR(255) DEFAULT NULL,
    level         INT          NOT NULL DEFAULT 1,
    points        INT          NOT NULL DEFAULT 0,
    is_admin      TINYINT      NOT NULL DEFAULT 0,
    status        TINYINT      NOT NULL DEFAULT 1 COMMENT '1 active, 2 muted, 3 banned',
    last_login_time DATETIME   DEFAULT NULL,
    last_login_ip VARCHAR(64)  DEFAULT NULL,
    create_time   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    is_deleted    TINYINT      NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    UNIQUE KEY uk_user_username (username),
    UNIQUE KEY uk_user_email (email),
    KEY idx_user_status (status),
    KEY idx_user_create_time (create_time)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- Refresh tokens double as the logout blacklist: a row means the token is dead.
CREATE TABLE IF NOT EXISTS sys_token (
    id             BIGINT      NOT NULL,
    user_id        BIGINT      NOT NULL,
    token_hash     VARCHAR(128) NOT NULL,
    token_type     VARCHAR(16) NOT NULL COMMENT 'ACCESS or REFRESH',
    expires_at     DATETIME    NOT NULL,
    revoked        TINYINT     NOT NULL DEFAULT 0,
    revoke_time    DATETIME    DEFAULT NULL,
    create_time    DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_token_hash (token_hash),
    KEY idx_token_user (user_id),
    KEY idx_token_expires (expires_at)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- Registration / login / password reset verification codes.
CREATE TABLE IF NOT EXISTS sys_verify_code (
    id          BIGINT      NOT NULL,
    target      VARCHAR(128) NOT NULL,
    code        VARCHAR(16)  NOT NULL,
    scene       VARCHAR(32)  NOT NULL COMMENT 'REGISTER, LOGIN or RESET_PASSWORD',
    used        TINYINT      NOT NULL DEFAULT 0,
    expires_at  DATETIME     NOT NULL,
    create_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_verify_target_scene (target, scene),
    KEY idx_verify_expires (expires_at)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Forum categories
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS forum_category (
    id          BIGINT       NOT NULL,
    name        VARCHAR(64)  NOT NULL,
    description VARCHAR(255) DEFAULT NULL,
    icon        VARCHAR(64)  DEFAULT NULL,
    sort_order  INT          NOT NULL DEFAULT 0,
    post_count  INT          NOT NULL DEFAULT 0,
    status      TINYINT      NOT NULL DEFAULT 1,
    create_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    is_deleted  TINYINT      NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    KEY idx_category_sort (sort_order),
    KEY idx_category_status (status)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Posts: the list projection and the body live in separate tables.
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS forum_post (
    id            BIGINT       NOT NULL,
    category_id   BIGINT       NOT NULL,
    user_id       BIGINT       NOT NULL,
    title         VARCHAR(128) NOT NULL,
    summary       VARCHAR(500) DEFAULT NULL,
    cover_url     VARCHAR(255) DEFAULT NULL,
    view_count    INT          NOT NULL DEFAULT 0,
    comment_count INT          NOT NULL DEFAULT 0,
    like_count    INT          NOT NULL DEFAULT 0,
    collect_count INT          NOT NULL DEFAULT 0,
    report_count  INT          NOT NULL DEFAULT 0,
    is_top        TINYINT      NOT NULL DEFAULT 0,
    is_essential  TINYINT      NOT NULL DEFAULT 0,
    status        TINYINT      NOT NULL DEFAULT 1 COMMENT '1 published, 2 pending audit, 3 rejected, 4 deleted',
    audit_user_id BIGINT       DEFAULT NULL,
    audit_time    DATETIME     DEFAULT NULL,
    audit_reason  VARCHAR(255) DEFAULT NULL,
    create_time   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    is_deleted    TINYINT      NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    KEY idx_post_category_status (category_id, status, is_top, create_time),
    KEY idx_post_user (user_id, status),
    KEY idx_post_status_create (status, create_time),
    KEY idx_post_essential (is_essential, status)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS forum_post_content (
    post_id     BIGINT NOT NULL,
    content_md  MEDIUMTEXT NOT NULL,
    update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (post_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS forum_post_like (
    id          BIGINT   NOT NULL,
    post_id     BIGINT   NOT NULL,
    user_id     BIGINT   NOT NULL,
    create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_post_like (post_id, user_id),
    KEY idx_post_like_user (user_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS forum_post_collect (
    id          BIGINT   NOT NULL,
    post_id     BIGINT   NOT NULL,
    user_id     BIGINT   NOT NULL,
    create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_post_collect (post_id, user_id),
    KEY idx_post_collect_user (user_id, create_time)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS forum_post_tag (
    id          BIGINT      NOT NULL,
    post_id     BIGINT      NOT NULL,
    tag_name    VARCHAR(48) NOT NULL,
    create_time DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_post_tag_post (post_id),
    KEY idx_post_tag_name (tag_name)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Comments with reply support (two level display)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS forum_comment (
    id           BIGINT   NOT NULL,
    post_id      BIGINT   NOT NULL,
    user_id      BIGINT   NOT NULL,
    parent_id    BIGINT   DEFAULT NULL COMMENT 'null for a root comment, otherwise the replied comment',
    root_id      BIGINT   DEFAULT NULL COMMENT 'root comment of the thread, used to group replies',
    reply_user_id BIGINT  DEFAULT NULL,
    content      VARCHAR(2000) NOT NULL,
    like_count   INT      NOT NULL DEFAULT 0,
    reply_count  INT      NOT NULL DEFAULT 0,
    status       TINYINT  NOT NULL DEFAULT 1 COMMENT '1 visible, 2 pending audit, 3 deleted',
    audit_time   DATETIME DEFAULT NULL,
    create_time  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    is_deleted   TINYINT  NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    KEY idx_comment_post_status (post_id, status, create_time),
    KEY idx_comment_parent (parent_id),
    KEY idx_comment_root (root_id, create_time),
    KEY idx_comment_user (user_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS forum_comment_like (
    id          BIGINT   NOT NULL,
    comment_id  BIGINT   NOT NULL,
    user_id     BIGINT   NOT NULL,
    create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_comment_like (comment_id, user_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Sensitive words
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS forum_sensitive_word (
    id          BIGINT       NOT NULL,
    word        VARCHAR(128) NOT NULL,
    category    VARCHAR(32)  NOT NULL DEFAULT 'DEFAULT',
    replace_with VARCHAR(16) NOT NULL DEFAULT '***',
    status      TINYINT      NOT NULL DEFAULT 1,
    create_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_sensitive_word (word),
    KEY idx_sensitive_status (status)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Reports against posts and comments
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS forum_report (
    id            BIGINT       NOT NULL,
    target_type   VARCHAR(16)  NOT NULL COMMENT 'POST or COMMENT',
    target_id     BIGINT       NOT NULL,
    reporter_id   BIGINT       NOT NULL,
    reason_code   VARCHAR(32)  NOT NULL,
    reason_detail VARCHAR(500) DEFAULT NULL,
    status        TINYINT      NOT NULL DEFAULT 0 COMMENT '0 pending, 1 accepted, 2 rejected',
    handle_user_id BIGINT      DEFAULT NULL,
    handle_time   DATETIME     DEFAULT NULL,
    handle_note   VARCHAR(255) DEFAULT NULL,
    create_time   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_report_target_user (target_type, target_id, reporter_id),
    KEY idx_report_status_create (status, create_time),
    KEY idx_report_target (target_type, target_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Notifications
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS forum_notification (
    id          BIGINT       NOT NULL,
    user_id     BIGINT       NOT NULL,
    type        VARCHAR(32)  NOT NULL COMMENT 'COMMENT, REPLY, LIKE, SYSTEM, REPORT_RESULT',
    title       VARCHAR(128) NOT NULL,
    content     VARCHAR(500) DEFAULT NULL,
    target_type VARCHAR(16)  DEFAULT NULL,
    target_id   BIGINT       DEFAULT NULL,
    is_read     TINYINT      NOT NULL DEFAULT 0,
    read_time   DATETIME     DEFAULT NULL,
    create_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_notification_user_read (user_id, is_read, create_time)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Operation log for admin auditing
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS sys_operation_log (
    id           BIGINT       NOT NULL,
    user_id      BIGINT       DEFAULT NULL,
    username     VARCHAR(64)  DEFAULT NULL,
    module       VARCHAR(64)  NOT NULL,
    operation    VARCHAR(128) NOT NULL,
    method       VARCHAR(255) DEFAULT NULL,
    params       VARCHAR(1000) DEFAULT NULL,
    result       VARCHAR(32)  DEFAULT NULL,
    ip           VARCHAR(64)  DEFAULT NULL,
    user_agent   VARCHAR(255) DEFAULT NULL,
    cost_ms      BIGINT       DEFAULT NULL,
    create_time  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_op_log_user (user_id, create_time),
    KEY idx_op_log_module (module, create_time)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Uploaded files
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS sys_file (
    id            BIGINT       NOT NULL,
    original_name VARCHAR(255) NOT NULL,
    stored_name   VARCHAR(128) NOT NULL,
    bucket_name   VARCHAR(64)  NOT NULL,
    object_key    VARCHAR(255) NOT NULL,
    url           VARCHAR(500) NOT NULL,
    content_type  VARCHAR(128) DEFAULT NULL,
    size          BIGINT       NOT NULL DEFAULT 0,
    uploader_id   BIGINT       NOT NULL,
    create_time   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_file_object_key (object_key),
    KEY idx_file_uploader (uploader_id, create_time)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;
